import React, { useState } from "react";
import AchievementsPanel from "./AchievementsPanel";
import UserProfileCard from './UserProfileCard';

export default function AdminDashboard({ reports, token, setMsg, admin }) {
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);
  const [mostActive, setMostActive] = useState(null);

  const API = process.env.REACT_APP_API || "http://localhost:4000";

  // --- Styles Objects for cleaner JSX ---
  const styles = {
    // General styles for container, card, buttons, etc.
    sidebarBox: {
      padding: 16,
      borderRadius: 12,
      boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.1)",
      marginBottom: 16,
      border: "1px solid #e2e8f0",
    },
    // Styles for the main report stats (neutral background)
    statCard: {
        background: "#fff", // Removed specific colors
        border: "1px solid #e2e8f0",
        flex: 1, 
        textAlign: "center", 
        padding: "16px", 
        borderRadius: 12,
        boxShadow: "0 1px 3px 0 rgba(0, 0, 0, 0.1)",
    },
    // Colors for the STAT TEXT
    statTextDonations: { fontSize: "24px", fontWeight: "800", color: "#0ea5e9" },
    statTextVolunteers: { fontSize: "24px", fontWeight: "800", color: "#22c55e" },
    statTextFeedback: { fontSize: "24px", fontWeight: "800", color: "#ec4899" },

    // Sidebar Specific Colored Boxes (KEPT these colors)
    quickActionsBox: {
      background: "#ecfdf5", // Light Teal/Mint
      border: "1px solid #a7f3d0",
    },
    mostActiveNgoBox: {
      background: "#fef3f7", // Light Rose/Pink
      border: "1px solid #fecdd3",
    },
    userFeedbackBox: {
      background: "#fffbeb", // Light Yellow/Cream
      border: "1px solid #fde68a",
      maxHeight: 250,
      overflowY: "auto",
    },
    buttonSecondary: {
        width: "100%",
        padding: 10,
        borderRadius: 8,
        marginBottom: 8,
        cursor: "pointer",
        fontWeight: 600,
        background: "#e0e7ff",
        color: "#4f46e5",
        border: "1px solid #c7d2fe",
        transition: "background 0.2s",
    },
    reportContainer: {
        display: "flex", 
        gap: 24, 
        alignItems: "flex-start",
        maxWidth: "1200px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "'Inter', 'Segoe UI', sans-serif",
    },
    mainContent: {
        flex: 1,
    }
  };

  const clearAll = () => {
    setNgos(null);
    setEvents(null);
    setEventStats(null);
    setMostActive(null);
  };

  const loadData = async (endpoint, setter, expectedField = null, errMsg = "Failed to load") => {
    if (!token) return setMsg("Login as admin first");

    clearAll();

    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || errMsg);
        } catch {
          throw new Error(errMsg);
        }
      }

      const data = await res.json();

      if (expectedField && (data[expectedField] !== undefined && data[expectedField] !== null)) {
        setter(data[expectedField]);
        return;
      }

      const fallbackCandidates = [
        "top", "mostActive", "most", "badges", "ngos", "events",
        "volunteers", "donors", "results", "participants",
        "donations", "user_badges",
      ];

      for (const key of fallbackCandidates) {
        if (data[key] !== undefined && data[key] !== null) {
          setter(data[key]);
          return;
        }
      }

      if (Array.isArray(data)) {
        setter(data);
        return;
      }

      setter(data);
    } catch (err) {
      console.error(err);
      setMsg(err.message || errMsg);
    }
  };

  const loadMostActive = async () => {
    if (!token) return setMsg("Login as admin first");

    clearAll();

    try {
      const res = await fetch(`${API}/api/actions/most-active-ngo`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || "Failed to load most active NGO");
        } catch {
          throw new Error("Failed to load most active NGO");
        }
      }

      const data = await res.json();

      const candidate = data.mostActive || data.most || data.top || data.most_active || data[0] || null;

      if (Array.isArray(candidate)) {
        setMostActive(candidate[0] || null);
      } else {
        setMostActive(candidate || null);
      }
    } catch (err) {
      console.error(err);
      setMsg(err.message || "Failed to load most active NGO");
    }
  };

  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");
    if (!window.confirm("Are you sure you want to remove this NGO?")) return;

    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || "Failed to delete NGO");
        } catch {
          throw new Error("Failed to delete NGO");
        }
      }

      setMsg("NGO removed successfully");

      setNgos((prev) => (Array.isArray(prev) ? prev.filter((n) => n.id !== id) : prev));
    } catch (err) {
      console.error(err);
      setMsg(err.message);
    }
  };

  const renderResults = (results) => {
    if (!results) return null;

    const list = Array.isArray(results) ? results : [results];

    if (!list.length) return <p style={{ color: "#64748b", fontStyle: "italic" }}>No data found.</p>;

    const resultCardStyle = {
      padding: "12px",
      background: "#fff",
      borderRadius: "8px",
      marginBottom: "8px",
      border: "1px solid #e2e8f0",
      boxShadow: "0 1px 2px rgba(0,0,0,0.05)",
    };

    return list.map((item, i) => {
      // Logic for Event/Title results
      if (item.title || item.event_title) {
        const title = item.title || item.event_title;
        const date = item.date || item.created_at || item.event_date;
        return (
          <div key={item.id || i} style={resultCardStyle}>
            <strong style={{ display: "block", fontSize: "15px", color: "#1e293b", marginBottom: "4px" }}>{title}</strong>
            {date && <div style={{ fontSize: 12, color: "#64748b" }}>📅 {new Date(date).toLocaleDateString()}</div>}
            
            <div style={{ display: "flex", gap: "10px", fontSize: "12px", color: "#475569", marginTop: "6px" }}>
                {item.volunteers_count !== undefined && (
                  <span style={{ background: "#f1f5f9", padding: "3px 6px", borderRadius: "4px" }}>
                    Users: <strong>{item.volunteers_count}</strong>
                  </span>
                )}
                {item.donations_sum !== undefined && (
                  <span style={{ background: "#ecfccb", color: "#3f6212", padding: "3px 6px", borderRadius: "4px" }}>
                    Raised: <strong>₹{item.donations_sum}</strong>
                  </span>
                )}
            </div>
          </div>
        );
      }

      // Logic for User/Donor/NGO results
      if (item.name || item.user_name || item.donor_name || item.email) {
        const name = item.name || item.user_name || item.donor_name || item.email;
        return (
          <div
            key={item.id || i}
            style={{
              ...resultCardStyle,
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <div>
              <strong style={{ fontSize: "14px", display: "block" }}>{name}</strong>
              {item.email && <div style={{ fontSize: 12, color: "#64748b" }}>{item.email}</div>}
              <div style={{ marginTop: "4px", display: "flex", gap: "8px" }}>
                 {item.amount !== undefined && <span style={{fontSize: 12, fontWeight: "bold", color: "#059669"}}>₹{item.amount}</span>}
                 {item.points !== undefined && <span style={{fontSize: 12, color: "#d97706"}}>★ {item.points} pts</span>}
              </div>
            </div>

            <div style={{ fontSize: 11, color: "#94a3b8", textAlign: "right" }}>
              {item.created_at && <div>{new Date(item.created_at).toLocaleDateString()}</div>}
            </div>
          </div>
        );
      }

      // Logic for Badge/Generic results
      if (item.title && item.description) {
        return (
          <div key={item.key || i} style={resultCardStyle}>
            <strong style={{ color: "#4338ca", fontSize: "14px" }}>{item.title}</strong>
            <div style={{ fontSize: 13, color: "#475569", margin: "4px 0" }}>{item.description || item.desc}</div>
          </div>
        );
      }

      // Fallback
      return (
        <div key={i} style={{ ...resultCardStyle, background: "#f8fafc" }}>
          <pre style={{ margin: 0, whiteSpace: "pre-wrap", fontSize: "11px", color: "#334155" }}>{JSON.stringify(item, null, 2)}</pre>
        </div>
      );
    });
  };

  return (
    <div style={styles.reportContainer}>
      <div style={styles.mainContent}>
        
        {/* PROFILE HEADER */}
        <div
          style={{
            ...styles.sidebarBox,
            background: "#fff",
            display: "flex",
            alignItems: "center",
            gap: 12,
            marginBottom: 20,
          }}
        >
          <div
            style={{
              width: 48,
              height: 48,
              borderRadius: "50%",
              background: "#e0e7ff", // Soft indigo
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              fontSize: 22,
              fontWeight: 600,
              color: "#333",
            }}
          >
            👤
          </div>

          <div>
            <div style={{ fontWeight: 600, fontSize: 16 }}>
              {admin?.email || "admin@ngo.local"}
            </div>
            <div style={{ fontSize: 13, color: "#666" }}>Role: Admin</div>
          </div>
        </div>

        <AchievementsPanel
          token={token}
          me={{ points: reports?.adminPoints || 0 }}
          role="user"
          setMsg={setMsg}
        />

        <h3 style={{marginTop: "24px", color: "#334155"}}>Admin Reports</h3>

        {/* Stats Grid - Backgrounds removed here, using styles.statCard */}
        <div style={{ display: "flex", gap: "16px", marginBottom: "24px" }}>
          
          <div style={styles.statCard}>
            <div style={styles.statTextDonations}>
              {reports?.donations
                ? "₹" + reports.donations.reduce(
                    (sum, d) => sum + parseFloat(d.amount || 0),
                    0
                  ).toLocaleString()
                : "-"}
            </div>
            <div style={{ fontSize: "12px", fontWeight: "600", color: "#64748b", marginTop: "4px" }}>Total Donation Amount</div>
          </div>

          <div style={styles.statCard}>
            <div style={styles.statTextVolunteers}>{reports?.volunteers?.length || 0}</div>
            <div style={{ fontSize: "12px", fontWeight: "600", color: "#64748b", marginTop: "4px" }}>Total Volunteers</div>
          </div>

          <div style={styles.statCard}>
            <div style={styles.statTextFeedback}>{reports?.feedbacks?.length || 0}</div>
            <div style={{ fontSize: "12px", fontWeight: "600", color: "#64748b", marginTop: "4px" }}>Feedbacks Received</div>
          </div>
        </div>
        
        {/* Main Data Actions */}
        <div style={{...styles.sidebarBox, background: "#f8fafc", border: "1px dashed #cbd5e1"}}>
            <div style={{fontSize: "14px", fontWeight: "600", marginBottom: "12px", color: "#475569"}}>Data Controls</div>
          <button
            style={styles.buttonSecondary}
            onClick={() =>
              loadData("/api/actions/ngos", setNgos, "ngos", "Failed to load NGOs")
            }
          >
            View Registered NGOs
          </button>

          <button
            style={styles.buttonSecondary}
            onClick={() =>
              loadData(
                "/api/actions/registered-events",
                setEvents,
                "events",
                "Failed to load events"
              )
            }
          >
            View Registered Events
          </button>

          <button
            style={styles.buttonSecondary}
            onClick={() =>
              loadData(
                "/api/actions/event-stats",
                setEventStats,
                "events",
                "Failed to load event stats"
              )
            }
          >
            View Event Stats
          </button>
        </div>


        {/* Data Display Areas */}
        {events && (
          <div style={{ marginTop: 24 }}>
            <h4 style={{color: "#334155"}}>Registered Events</h4>
            {Array.isArray(events) && events.length ? (
              events.map((e) => (
                <div
                  key={e.id}
                  style={{
                    padding: 10,
                    background: "#fff",
                    borderRadius: 8,
                    marginBottom: 8,
                    borderLeft: "4px solid #0ea5e9"
                  }}
                >
                  <strong>{e.title}</strong>
                  <div style={{ fontSize: 13, color: "#64748b" }}>{e.date || e.created_at}</div>
                </div>
              ))
            ) : (
              <p>No events registered.</p>
            )}
          </div>
        )}

        {eventStats && (
          <div style={{ marginTop: 24 }}>
            <h4 style={{color: "#334155"}}>Query Results</h4>
            {renderResults(eventStats)}
          </div>
        )}

        {ngos && (
          <div style={{ marginTop: 24 }}>
            <h4 style={{color: "#334155"}}>Registered NGOs</h4>
            {Array.isArray(ngos) && ngos.length ? (
              ngos.map((n) => (
                <div
                  key={n.id}
                  style={{
                    padding: 10,
                    background: "#fff",
                    borderRadius: 8,
                    marginBottom: 8,
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    border: "1px solid #e2e8f0",
                  }}
                >
                  <div>
                    <strong>{n.name}</strong>
                    <div style={{ fontSize: 13, color: "#64748b" }}>{n.email}</div>
                  </div>

                  <button
                    style={{
                      padding: "6px 12px",
                      background: "#ef4444",
                      color: "white",
                      border: "none",
                      borderRadius: 6,
                      cursor: "pointer",
                      fontSize: "12px",
                      fontWeight: 600,
                    }}
                    onClick={() => deleteNgo(n.id)}
                  >
                    Remove
                  </button>
                </div>
              ))
            ) : (
              <p>No NGOs registered.</p>
            )}
          </div>
        )}
      </div>

      {/* RIGHT PANEL (STILL COLORFUL) */}
      <div
        style={{
          width: 280,
          flexShrink: 0,
          position: "sticky",
          top: 20, // Adjusted top sticky position
          display: "flex",
          flexDirection: "column",
          gap: 20, // Increased gap
        }}
      >

        {/* Quick Actions (KEPT COLOR) */}
        <div style={{ ...styles.sidebarBox, ...styles.quickActionsBox }}>
          <h4 style={{ marginTop: 0, color: "#065f46" }}>Quick Actions</h4>

          <button
            onClick={() =>
              loadData(
                "/api/actions/top-volunteers",
                setEventStats,
                "top",
                "Failed to load top volunteers"
              )
            }
            style={{...styles.buttonSecondary, background: "#d1fae5", color: "#065f46", border: "1px solid #a7f3d0"}}
          >
            🏆 Top Volunteers
          </button>

          <button
            onClick={() =>
              loadData(
                "/api/actions/top-donors",
                setEventStats,
                "top",
                "Failed to load top donors"
              )
            }
            style={{...styles.buttonSecondary, background: "#d1fae5", color: "#065f46", border: "1px solid #a7f3d0"}}
          >
            💰 Top Donors
          </button>

          <button
            onClick={() =>
              loadData(
                "/api/actions/badges",
                setEventStats,
                "badges",
                "Failed to load badges"
              )
            }
            style={{...styles.buttonSecondary, background: "#d1fae5", color: "#065f46", border: "1px solid #a7f3d0", marginBottom: 0}}
          >
            🎖️ View Badges
          </button>
        </div>

        {/* Most Active NGO (KEPT COLOR) */}
        <div style={{ ...styles.sidebarBox, ...styles.mostActiveNgoBox }}>
          <h4 style={{ marginTop: 0, color: "#be185d" }}>Most Active NGO</h4>

          <button
            onClick={loadMostActive}
            style={{ ...styles.buttonSecondary, marginTop: 8, padding: 8, width: "100%", borderRadius: 6, background: "#fbcfe8", color: "#831843", border: "1px solid #f9a8d4" }}
          >
            Load Most Active NGO
          </button>

          {mostActive && (
            <div style={{ marginTop: 12, padding: 8, background: "#fff", borderRadius: 8 }}>
              <strong style={{fontSize: "15px"}}>{mostActive.name}</strong>
              <div style={{ fontSize: 13, color: "#666" }}>
                Activity Score: <span style={{fontWeight: "bold", color: "#059669"}}>{(mostActive?.activity_score ?? mostActive?.activityScore ?? mostActive?.activity) ?? "N/A"}</span>
              </div>
            </div>
          )}
        </div>

        {/* ⭐ USER FEEDBACK BOX (KEPT COLOR) ⭐ */}
        <div style={{ ...styles.sidebarBox, ...styles.userFeedbackBox }}>
          <h4 style={{ marginTop: 0, color: "#92400e" }}>💬 User Feedback</h4>

          {reports?.feedbacks?.length ? (
            reports.feedbacks.map((f, i) => (
              <div
                key={i}
                style={{
                  background: "#fff",
                  padding: 10,
                  borderRadius: 8,
                  marginBottom: 10,
                  border: "1px solid #fef9c3",
                  fontSize: 13,
                }}
              >
                <div style={{display: "flex", justifyContent: "space-between", marginBottom: "4px"}}>
                    <strong style={{color: "#334155"}}>{f.email || f.name || "User"}</strong>
                    <span style={{ fontSize: 11, color: "#94a3b8" }}>
                    {new Date(f.created_at).toLocaleDateString()}
                    </span>
                </div>
                <div style={{ color: "#475569" }}>"{f.text}"</div>
              </div>
            ))
          ) : (
            <p style={{fontSize: 13, color: "#94a3b8", textAlign: "center"}}>No feedback available.</p>
          )}
        </div>

      </div>
    </div>
  );
}
